"use strict";(self.webpackChunkhn_cho_sh=self.webpackChunkhn_cho_sh||[]).push([[84694],{3331:(e,n,i)=>{i.d(n,{R:()=>a,x:()=>d});var r=i(36672);const t={},s=r.createContext(t);function a(e){const n=r.useContext(s);return r.useMemo((function(){return"function"==typeof e?e(n):{...n,...e}}),[n,e])}function d(e){let n;return n=e.disableParentContext?"function"==typeof e.components?e.components(t):e.components||t:a(e.components),r.createElement(s.Provider,{value:n},e.children)}},75835:(e,n,i)=>{i.r(n),i.d(n,{assets:()=>o,contentTitle:()=>d,default:()=>h,frontMatter:()=>a,metadata:()=>r,toc:()=>u});const r=JSON.parse('{"id":"2023/04/14","title":"2023-04-14","description":"Verhaftung im Mordfall Bob Lee in SF - mutma\xdflicher M\xf6rder arbeitete auch in der Tech-Branche","source":"@site/i18n/de/docusaurus-plugin-content-docs/current/2023/04/14.md","sourceDirName":"2023/04","slug":"/2023/04/14","permalink":"/de/2023/04/14","draft":false,"unlisted":false,"editUrl":"https://github.com/anaclumos/heimdall/blob/main/i18n/de/docusaurus-plugin-content-docs//current/2023/04/14.md","tags":[],"version":"current","frontMatter":{"localized_date":"14. April 2023","top_news":"Verhaftung im Mordfall Bob Lee in SF - mutma\xdflicher M\xf6rder arbeitete auch in der Tech-Branche"},"sidebar":"defaultSidebar","previous":{"title":"2023-04-15","permalink":"/de/2023/04/15"},"next":{"title":"2023-04-13","permalink":"/de/2023/04/13"}}');var t=i(23420),s=i(3331);const a={localized_date:"14. April 2023",top_news:"Verhaftung im Mordfall Bob Lee in SF - mutma\xdflicher M\xf6rder arbeitete auch in der Tech-Branche"},d="2023-04-14",o={},u=[{value:"Verhaftung im Mordfall Bob Lee in SF - mutma\xdflicher M\xf6rder arbeitete auch in der Tech-Branche",id:"verhaftung-im-mordfall-bob-lee-in-sf---mutma\xdflicher-m\xf6rder-arbeitete-auch-in-der-tech-branche",level:2},{value:"YouTube-DL-Hosting-Verbot ebnet den Weg zu privatisierter Zensur",id:"youtube-dl-hosting-verbot-ebnet-den-weg-zu-privatisierter-zensur",level:2},{value:"Die Kunst des Auto-Engineerings",id:"die-kunst-des-auto-engineerings",level:2},{value:"Apple wird bis 2025 zu 100 Prozent recyceltes Kobalt in Batterien verwenden",id:"apple-wird-bis-2025-zu-100-prozent-recyceltes-kobalt-in-batterien-verwenden",level:2},{value:"Wir haben die Startgeschwindigkeit von Podman um das 6-fache erh\xf6ht.",id:"wir-haben-die-startgeschwindigkeit-von-podman-um-das-6-fache-erh\xf6ht",level:2},{value:"Verbesserung von Tailscale durch Apples Open Source",id:"verbesserung-von-tailscale-durch-apples-open-source",level:2},{value:"Animierte Zeichnungen",id:"animierte-zeichnungen",level:2},{value:"Amazon CodeWhisperer, kostenlos f\xfcr den individuellen Gebrauch, ist jetzt allgemein verf\xfcgbar",id:"amazon-codewhisperer-kostenlos-f\xfcr-den-individuellen-gebrauch-ist-jetzt-allgemein-verf\xfcgbar",level:2},{value:"Google hat bereits sechs Produkte im Jahr 2023 vom Markt genommen.",id:"google-hat-bereits-sechs-produkte-im-jahr-2023-vom-markt-genommen",level:2},{value:"Nvidia RTX Remix Runtime Open Source jetzt verf\xfcgbar",id:"nvidia-rtx-remix-runtime-open-source-jetzt-verf\xfcgbar",level:2}];function l(e){const n={a:"a",h1:"h1",h2:"h2",header:"header",p:"p",...(0,s.R)(),...e.components};return(0,t.jsxs)(t.Fragment,{children:[(0,t.jsx)(n.header,{children:(0,t.jsx)(n.h1,{id:"2023-04-14",children:"2023-04-14"})}),"\n",(0,t.jsx)(n.h2,{id:"verhaftung-im-mordfall-bob-lee-in-sf---mutma\xdflicher-m\xf6rder-arbeitete-auch-in-der-tech-branche",children:"Verhaftung im Mordfall Bob Lee in SF - mutma\xdflicher M\xf6rder arbeitete auch in der Tech-Branche"}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"https://missionlocal.org/2023/04/bob-lee-killing-arrest-made-san-francisco/",children:"Original"}),".\nBei der Ermordung von Bob Lee, einem leitenden Angestellten der Technologiebranche, wurde ein Verd\xe4chtiger verhaftet, der ebenfalls in der Technologiebranche t\xe4tig und mit Lee bekannt war. Berichten zufolge fand die Polizei Lee und den Verd\xe4chtigen zusammen in einem Auto, das auf den Verd\xe4chtigen zugelassen war, und behauptet, dass eine Art Konfrontation stattfand, w\xe4hrend er im Auto sa\xdf und m\xf6glicherweise weiterfuhr, nachdem Lee das Auto verlassen hatte. Die Berichterstattung \xfcber Lees Tod wurde in eine Reihe mit anderen Ungl\xfccksf\xe4llen und Verbrechen der letzten Zeit in San Francisco gestellt, obwohl dies nicht die tats\xe4chliche Lebenserfahrung der meisten Einwohner San Franciscos widerspiegelt."]}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35555525",children:"Discussion Service"}),".\nDer Mord an einem leitenden Angestellten der Technologiebranche in San Francisco hat Diskussionen \xfcber Faktoren wie Obdachlosigkeit, psychische Gesundheit, Drogenabh\xe4ngigkeit und Armut ausgel\xf6st, die zu dem Verbrechen gef\xfchrt haben k\xf6nnten, aber Kommentatoren warnen vor Verallgemeinerungen. Es gibt auch eine Debatte \xfcber die Verwendung von Statistiken im Vergleich zu pers\xf6nlichen Anekdoten bei der Bewertung von Kriminalit\xe4tsraten und die Notwendigkeit eines gemeinschaftlichen Ansatzes, um die komplexen Probleme von Obdachlosigkeit, Sucht und Kriminalit\xe4t anzugehen. Die Nutzer betonen, wie wichtig es ist, die Kriminalit\xe4tsrate im Zusammenhang mit der Armut zu bewerten, anstatt verschiedene Kulturen zu vergleichen und keine voreiligen Schl\xfcsse aus einem einzigen Fall zu ziehen."]}),"\n",(0,t.jsx)(n.h2,{id:"youtube-dl-hosting-verbot-ebnet-den-weg-zu-privatisierter-zensur",children:"YouTube-DL-Hosting-Verbot ebnet den Weg zu privatisierter Zensur"}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"https://torrentfreak.com/youtube-dl-hosting-ban-paves-the-way-to-privatized-censorship-230411/",children:"Original"}),'.\nEin deutsches Gericht hat Uberspace f\xfcr das Hosten der Website von youtube-dl - einem Open-Source-Tool, das das Herunterladen von YouTube-Inhalten erm\xf6glicht - zur Verantwortung gezogen. Uberspace warnt davor, dass das Urteil zu einer privatisierten Zensur f\xfchren k\xf6nnte, und legt Berufung gegen die Entscheidung ein, obwohl das Gericht feststellte, dass Uberspace "daf\xfcr haftbar gemacht werden kann, dass es die G\xfcltigkeit einer Takedown-Anfrage anzweifelt", selbst wenn nicht klar war, dass das Tool gegen das Gesetz verst\xf6\xdft.']}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35553337",children:"Discussion Service"}),".\nDas Verbot des YouTube-DL-Hostings wird als ein Vorsto\xdf in Richtung privatisierter Zensur gesehen, wobei die RIAA und die MPAA Geld und Macht \xfcber den Anstand stellen. Die Rolle des geistigen Eigentums bei der Begrenzung des Informationsflusses wird diskutiert, wobei eine Reihe von Ansichten vertreten werden, darunter die Begrenzung von Umfang und Dauer. Die Nutzer schlagen Alternativen vor und prangern die Abh\xe4ngigkeit von GitHub an, w\xe4hrend sie die Dezentralisierung und Probleme mit der Sicherheit durch Unklarheit beim Kopierschutz diskutieren."]}),"\n",(0,t.jsx)(n.h2,{id:"die-kunst-des-auto-engineerings",children:"Die Kunst des Auto-Engineerings"}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"https://www.howacarworks.com/video-course",children:"Original"}),".\nThe Art of Auto Engineering ist ein kompletter Videokurs, der aus mehr als 122 Lektionen mit 20 Stunden Filmmaterial besteht, in denen jedes einzelne Teil eines Autos bis ins kleinste Detail erkl\xe4rt wird, von den Grundlagen bis zur fortgeschrittenen Fahrzeugtechnik. Der Kurs wird von einem 200-seitigen Handbuch begleitet und ist online oder in iOS- und Android-Apps f\xfcr eine einmalige Zahlung von $25 mit lebenslangem Zugang erh\xe4ltlich. Der Kurs ist professionell in 4K-Qualit\xe4t mit vollst\xe4ndigen Untertiteln gefilmt. Der Kurs wird von den Zuschauern f\xfcr seine fesselnden Anweisungen und den hervorragenden Produktionswert gelobt."]}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35552393",children:"Discussion Service"}),".\nNutzer von Hacker News tauschen Erfahrungen aus und empfehlen Ressourcen zum Lernen \xfcber Automobiltechnik, einschlie\xdflich interaktiver Videokurse und spezieller Automodelle. Die Kommentatoren diskutieren die Vorteile des Verst\xe4ndnisses von Automechanik, die Grenzen des alleinigen Verlassens auf KI und geben Tipps f\xfcr Autoreparaturen zum Selbermachen. Au\xdferdem debattieren die Nutzer \xfcber den Nutzen von kostenpflichtigen Kursen und Tools, und einige kritisieren das Auftauchen von Werbung f\xfcr kostenpflichtige Kurse auf der Website."]}),"\n",(0,t.jsx)(n.h2,{id:"apple-wird-bis-2025-zu-100-prozent-recyceltes-kobalt-in-batterien-verwenden",children:"Apple wird bis 2025 zu 100 Prozent recyceltes Kobalt in Batterien verwenden"}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"https://www.apple.com/newsroom/2023/04/apple-will-use-100-percent-recycled-cobalt-in-batteries-by-2025/",children:"Original"}),".\nApple hat angek\xfcndigt, bis 2025 in allen von Apple entwickelten Batterien 100 % recyceltes Kobalt zu verwenden, ebenso wie vollst\xe4ndig recycelte Seltene Erden f\xfcr Magnete und 100 % recyceltes Zinn f\xfcr Leiterplatten. Das Unternehmen hat sich zum Ziel gesetzt, ausschlie\xdflich recycelte und erneuerbare Materialien zu verwenden, und bezieht bereits mehr als 95 % des Wolframs, fast drei Viertel der Seltenen Erden und \xfcber zwei Drittel des Aluminiums aus 100 % recyceltem Material. Apple setzt Augmented Reality (AR) ein, um die Demontage von Ger\xe4ten f\xfcr Recyclingpartner zu leiten und die R\xfcckgewinnung von Seltenen Erden zu steigern und so einen branchenweiten Wandel hin zu einer geringeren Abh\xe4ngigkeit von neu abgebauten Mineralien voranzutreiben."]}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35554270",children:"Discussion Service"}),".\nApple hat angek\xfcndigt, bis 2025 zu 100 % recyceltes Kobalt in Batterien zu verwenden und den Plastikm\xfcll zu reduzieren, aber die Nutzer diskutieren \xfcber die Wirksamkeit dieser \xc4nderungen und dar\xfcber, ob das Unternehmen seine Recycling-Technologie \xf6ffentlich machen sollte. Die Debatte \xfcber vom Benutzer austauschbare Batterien geht weiter, mit Argumenten, dass sie umweltsch\xe4dlich sind, w\xe4hrend andere vorschlagen, dass Recycling-Methoden und die Verl\xe4ngerung der Lebensdauer von Produkten dieses Problem l\xf6sen k\xf6nnen. Apples Engagement f\xfcr wiederverwertbare Materialien und eine kohlenstoffneutrale Lieferkette wird gelobt, aber f\xfcr das Design und die Kobalt-Lieferkette kritisiert. Nutzer diskutieren \xfcber die Lebensdauer von iPhones und Android-Telefonen sowie \xfcber Recyclingmethoden f\xfcr Batterien. Einige Nutzer empfehlen MagSafe-Akkus als Hauptakku f\xfcr iPhones, w\xe4hrend andere ihre Effizienz in Frage stellen."]}),"\n",(0,t.jsx)(n.h2,{id:"wir-haben-die-startgeschwindigkeit-von-podman-um-das-6-fache-erh\xf6ht",children:"Wir haben die Startgeschwindigkeit von Podman um das 6-fache erh\xf6ht."}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"https://www.redhat.com/sysadmin/speed-containers-podman-raspberry-pi",children:"Original"}),".\nRed Hats Container-Engine Podman konnte die Startgeschwindigkeit um das 6-fache erh\xf6hen, indem unn\xf6tige Prozesse entfernt und kleinere Ineffizienzen behoben wurden, die sich auf kritische Anwendungen wie Autos auswirken, bei denen der Start von Containern nahezu in Echtzeit erforderlich ist. Das Team verwendete transienten Speicher und stellte Workarounds f\xfcr Kernel-Probleme bereit, was zu einem schnelleren Start von Containern f\xfchrte. Die Verwendung der Option --transient-store ist ideal f\xfcr Edge-Ger\xe4te, obwohl Mixed-Mode-Container nicht unterst\xfctzt werden."]}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35551830",children:"Discussion Service"}),".\nRed Hats Podman sieht eine Versechsfachung der Startgeschwindigkeit f\xfcr Autos, obwohl Discussion Service-Benutzer die \xdcberkompliziertheit moderner Autos diskutieren und Bedenken \xfcber Zuverl\xe4ssigkeit und Wartung \xe4u\xdfern. Die Diskussion geht in Debatten \xfcber das Recht auf Reparatur, den Einsatz von Microservices und Containern und das Gleichgewicht zwischen technologischen Fortschritten und Praktikabilit\xe4t \xfcber."]}),"\n",(0,t.jsx)(n.h2,{id:"verbesserung-von-tailscale-durch-apples-open-source",children:"Verbesserung von Tailscale durch Apples Open Source"}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"https://tailscale.dev/blog/darwin-spelunking",children:"Original"}),'.\nDas Tailscale-Team nutzte Apples Open Source, um Fehler im Zusammenhang mit der Netzwerkschnittstelle f\xfcr die Version 1.36 zu beheben, indem es sich auf ifconfig st\xfctzte, um die aktive Netzwerkschnittstelle zu bestimmen. Wenn Tailscale so konfiguriert ist, dass ein Exit-Node verwendet wird, wird dieser zur Standardroute, so dass ein Fix notwendig ist, um Netzwerkanfragen konsistent an die aktive Netzwerkschnittstelle zu "binden", ohne Schleifen zu verursachen. SIOCGIFDELEGATE, verf\xfcgbar \xfcber ioctl, erm\xf6glicht es, die zugrundeliegende physikalische Schnittstelle zu ermitteln und wurde in den Tailscale-Code f\xfcr macOS und iOS implementiert.']}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35559124",children:"Discussion Service"}),".\nDiscussion Service-Nutzer diskutieren die Vorteile und Herausforderungen von Open- und Closed-Source-Software bei der Verbesserung von Tailscale durch Apples Open Source. Einige zahlende Kunden legen Wert auf den Ruf des Open-Source-Kernprodukts von Tailscale, w\xe4hrend andere spezifische Probleme mit Tailscale ansprechen, wie z. B. Schwierigkeiten beim Zugriff auf Netzwerkfreigaben unter Windows 11 und potenzielle Batterieentladung auf iOS-Ger\xe4ten. Die Diskussion unterstreicht, wie wichtig es ist, verschiedene Perspektiven zu ber\xfccksichtigen, und dass Tailscale aufgrund seines Mesh-Systems und der kontinuierlichen Bereitstellung neuer Funktionen gegen\xfcber Zerotier an Zugkraft gewinnt, aber f\xfcr einige Produktnutzer bestehen Bedenken hinsichtlich der Einnahmen und des Burggrabens."]}),"\n",(0,t.jsx)(n.h2,{id:"animierte-zeichnungen",children:"Animierte Zeichnungen"}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"https://fairanimateddrawings.com/site/home",children:"Original"}),'.\nDas "Animated Drawings"-Repository auf Github implementiert den Algorithmus, der in dem Papier "A Method for Automatically Animating Children\'s Drawings of the Human Figure" beschrieben wird, und erm\xf6glicht es Benutzern, benutzerdefinierte Animationen mit ihren eigenen handgezeichneten Figuren zu erstellen. Der Installationsprozess ist einfach, und die Konfigurationsdateien k\xf6nnen ge\xe4ndert werden, um verschiedene Optionen, einschlie\xdflich Ausgabeformate und Hintergrundbilder, zu \xe4ndern. Das Repository bietet auch Skripte und Modelle f\xfcr die Animation pers\xf6nlicher Zeichnungen, und eine browserbasierte Demo ist f\xfcr eine schnelle und einfache Nutzung verf\xfcgbar.']}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35561203",children:"Discussion Service"}),".\nDas Projekt Fair Animated Drawings animiert Zeichnungen mit Code und ist in einer browserbasierten und einer GitHub-Version verf\xfcgbar. Die Nutzer sind an seinem Potenzial f\xfcr Gesch\xe4ftsideen interessiert und hoffen auf eine Android-App-Version. Eine relevante Arbeit zur nicht-fotorealistischen Posensch\xe4tzung namens Gesture3D scheint f\xfcr einen bestimmten Anwendungsfall geeignet zu sein, und Bewerbungen f\xfcr den YC-Sommer 2023 sind m\xf6glich."]}),"\n",(0,t.jsx)(n.h2,{id:"amazon-codewhisperer-kostenlos-f\xfcr-den-individuellen-gebrauch-ist-jetzt-allgemein-verf\xfcgbar",children:"Amazon CodeWhisperer, kostenlos f\xfcr den individuellen Gebrauch, ist jetzt allgemein verf\xfcgbar"}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"https://aws.amazon.com/blogs/aws/amazon-codewhisperer-free-for-individual-use-is-now-generally-available/",children:"Original"}),".\nAmazon CodeWhisperer, ein Echtzeit-KI-Codierungsbegleiter, ist jetzt allgemein verf\xfcgbar und umfasst eine CodeWhisperer Individual-Stufe, die von allen Entwicklern kostenlos genutzt werden kann. Das Tool hilft Entwicklern, schnell und sicher Code zu schreiben, ohne ihre IDE zu verlassen. CodeWhisperer bietet Vorschl\xe4ge f\xfcr allgemeine Anwendungsf\xe4lle in einer Vielzahl von Sprachen und kann Code-Vorschl\xe4ge filtern oder kennzeichnen, die bestimmten Open-Source-Trainingsdaten \xe4hneln, um das Risiko der Verwendung von potenziell voreingenommenem oder fehlerhaftem Code zu verringern."]}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35554460",children:"Discussion Service"}),".\nAmazon CodeWhisperer ist jetzt allgemein verf\xfcgbar und unterst\xfctzt mehrere Sprachen, darunter Python, Java, JavaScript, TypeScript und C#. Obwohl Copilot Berichten zufolge besser ist als CodeWhisperer, ist letzterer ein n\xfctzliches Tool, das dazu f\xfchren k\xf6nnte, dass KI-generierter Code zur Norm wird. Dar\xfcber hinaus hat Amazon CodeGuru Reviewer auf den Markt gebracht, ein KI-Tool, das Code scannt, um Probleme zu identifizieren und Korrekturen zur Effizienzsteigerung und Kostensenkung zu empfehlen."]}),"\n",(0,t.jsx)(n.h2,{id:"google-hat-bereits-sechs-produkte-im-jahr-2023-vom-markt-genommen",children:"Google hat bereits sechs Produkte im Jahr 2023 vom Markt genommen."}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"https://toolhub.tech/blog/Google-2023-Shutdown-Spree-6-Products-Pulled-in-Just-4-Months/",children:"Original"}),".\nGoogle hat in den ersten vier Monaten des Jahres 2023 bereits sechs Produkte eingestellt, darunter den Programmierwettbewerb Code Jam, die Social-Media-Plattform Google Currents, die Street-View-App, die Wearable-Tech-L\xf6sung Google Jacquard, den Cloud-Gaming-Dienst Google Stadia und den WLAN-Router Google OnHub. W\xe4hrend einige dieser Produkte \xfcber ein Jahrzehnt alt waren, wurde Google f\xfcr seine Angewohnheit, beliebte Dienste abrupt zu beenden, kritisiert."]}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35553421",children:"Discussion Service"}),".\nGoogle hat sechs Produkte im Jahr 2023 eingestellt, wobei es Bedenken hinsichtlich der Transparenz und der Produktkennzeichnung sowie der mangelnden Unterst\xfctzung f\xfcr gescheiterte Projekte wie Google Glass und Google Plus gab. W\xe4hrend die Cloud-Einheit mit einem Marktanteil von 10 % w\xe4chst, werden Bedenken hinsichtlich des Engagements von Kunden und Entwicklern sowie des Algorithmus zum T\xf6ten von Konten laut. Die Nutzer diskutieren \xfcber L\xf6sungen und Kosten zur Verbesserung der Genauigkeit von ChatGPT, w\xe4hrend Googles Ruf, Projekte aufzugeben, Kritik an der Produktunterst\xfctzung f\xfcr Verbraucher hervorruft."]}),"\n",(0,t.jsx)(n.h2,{id:"nvidia-rtx-remix-runtime-open-source-jetzt-verf\xfcgbar",children:"Nvidia RTX Remix Runtime Open Source jetzt verf\xfcgbar"}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"https://www.nvidia.com/en-us/geforce/news/rtx-remix-runtime-open-source-download/",children:"Original"}),".\nNvidia hat die RTX Remix-Runtime ver\xf6ffentlicht, eine Open-Source-Modding-Plattform f\xfcr das Remastering klassischer DirectX 8- und 9-Spiele mit Path Tracing, KI-verbesserten Texturen und benutzerdefinierten Assets. Mit dem RTX Remix Creator Toolkit k\xf6nnen Modder neue Objekte und Lichter innerhalb einer remasterten Szene zuweisen und mit KI-Tools das Aussehen eines beliebigen Objekts neu gestalten. Die RTX Remix-Laufzeit hingegen erfasst eine Spielszene, ersetzt Assets bei der Wiedergabe und f\xfcgt RTX-Technologie wie Path Tracing, DLSS 3 und Reflex in das Spiel ein."]}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35552378",children:"Discussion Service"}),".\nNvidia hat seine Open-Source-RTX-Remix-Runtime ver\xf6ffentlicht, die es Benutzern erm\xf6glicht, \xe4ltere Spiele mit Raytracing in Echtzeit zu spielen, obwohl nicht alle Spiele funktionieren. Nutzer von Hacker News diskutieren \xfcber die Bedeutung von Open-Source-Treibern im Vergleich zu propriet\xe4ren Treibern, Nvidias Ruf und die schlechte Leistung von RTX auf Nicht-Nvidia-Hardware. Die Nutzer spekulieren auch \xfcber eine m\xf6gliche Bevorzugung und schlagen vor, Entwickler von Kryptow\xe4hrungen zu unterst\xfctzen, die GPU-only Proof-of-Work-Systeme implementieren. Ein Nutzer verweist auf Remedys Entwicklung von Remakes von Max Payne PC-Spielen unter Verwendung von Remix und diskutiert die Frame-Pacing- und Ruckelprobleme der Technologie."]})]})}function h(e={}){const{wrapper:n}={...(0,s.R)(),...e.components};return n?(0,t.jsx)(n,{...e,children:(0,t.jsx)(l,{...e})}):l(e)}}}]);